import{_ as o,l,o as e,c as i,v as t,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"分部与地域","description":"","frontmatter":{"title":"分部与地域","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/segment-geo.md","filePath":"quant/segment-geo.md","lastUpdated":1789023840000}'),E={name:"quant/segment-geo.md"};function c(m,a,_,u,A,P){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="分部与地域" tabindex="-1">分部与地域 <a class="header-anchor" href="#分部与地域" aria-label="Permalink to &quot;分部与地域&quot;">​</a></h1><div class="epigraph"><p>合并报表把多元业务加总成一个账面和一个利润；分部披露把加总拆开，但可用日期更晚、口径更不稳，且同样存在 PIT 与幸存者。</p><footer>—— 据 SFAS 131 / IFRS 8 经营分部；Penman 对分部分析的讨论整理</footer></div><p>上一课<a href="/quant/fundamental-factor-source">基本面因子从哪张表来</a>把因子指回合并报表字段。多元化公司的总部行业代码只是一个标签：利润可能来自完全不同的业务与法域。本课补分部与地域披露能改什么、不能改什么。不重画因子索引，不为宏观国别配置开新课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合并利润表给出一个 ROE、一个应计。若公司一半是高应计制造、一半是现金奶牛金融，合并应计是加权平均，行业中性也救不了——因为它被放进了错误的行业桶。分部收入、分部经营利润、地域收入提供拆分。缺口是这些数字的可用日期通常随年报附注，细于合并主表的字段更少、时间序列更短、管理层可重组分部切割。用今天的分部结构回填十年，是又一次 restatement。</p><p>地域还带来税率与货币：上一课有效税率在跨国合并里已经被配比扭曲；地域披露只是让扭曲可被定位，不是自动给出各国法定税率因子。</p><h3 id="分部利润不是独立公司的净利润" tabindex="-1">分部利润不是独立公司的净利润 <a class="header-anchor" href="#分部利润不是独立公司的净利润" aria-label="Permalink to &quot;分部利润不是独立公司的净利润&quot;">​</a></h3><p>分部经营利润通常不含全部共同费用、利息与税，也不能加总还原成合并净利润而不做调节。用分部经营利润去除合并账面，或把分部当成可空头的上市实体，口径错误。本课把分部当<strong>合并字段的拆分信息</strong>，当不了另一套三张表。</p><p><span class="marginnote">SFAS 131 按「管理层视角」切分部，公司一改内部报告，历史分部就不可比。PIT 要保留当时切割，不要用新切割重做旧年。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优先用合并主表做可复制因子；分部用于：（1）修正行业归属（按收入或利润加权映射到多个行业，而不是单一总部代码）；（2）识别单一分部主导 vs 真正多元；（3）事件研究里对暴露某地域或某业务线的公司分组。全部使用附注的可用日期，通常不早于年报公告。不要用分析师对分部的事后拆分回填——那是另一层预期库，且常不存在 PIT。</p><p>缺失分部的公司（单一业务或不披露）应留在样本并标记，而不是删掉造成幸存者。</p>',12)),(e(),s(h,null,{default:r(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CON%5B%22%E5%90%88%E5%B9%B6%E4%B8%89%E5%BC%A0%E8%A1%A8%22%5D%20--%3E%20FAC%5B%22%E4%B8%BB%E5%B9%B2%E5%9B%A0%E5%AD%90%22%5D%0A%20%20SEG%5B%22%E5%88%86%E9%83%A8%E9%99%84%E6%B3%A8%20PIT%22%5D%20--%3E%20IND%5B%22%E5%8A%A0%E6%9D%83%E8%A1%8C%E4%B8%9A%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20SEG%20--%3E%20GEO%5B%22%E5%9C%B0%E5%9F%9F%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20IND%20--%3E%20FAC%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>分部加权行业暴露只用于修正总部代码明显错配的多元公司，例如收入一半来自完全不同的 GICS 一级。权重来自当时附注，下次年报前不变。不要把分部经营利润加总当合并净利润去算 ROE，共同费用与税不在分部里。地域收入地图不能拿去空一组国家 ETF，除非你另有可交易工具且声明不是本课方法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分部把「不可比」从行业代码推进到业务构成。对价值因子，多元公司的账面是各业务账面之和减去共同项，市值是一个数，倍数被混合业务折中。对惊喜因子，合并 EPS 意外可能来自某一个分部，窗口回报却记在整个代码上——这不是错误，是证券定义；只是解释 alpha 时不能把它当成该分部可单独交易。后课租赁与少数股东会进一步改合并口径，分部无法替代这些调整。</p><p><span class="marginnote">地域收入常按客户所在地而非风险所在地。用它当国家风险因子要非常克制，否则只是把销售地图当成暴露。</span></p><p>主干因子仍用合并 PIT 字段。分部只用于暴露：按当时附注的收入或经营利润加权到行业或地域，权重在下次年报前保持，除非公司发布明确的分部重组。不要用卖方事后拆分的分部盈利回填。缺失分部的观测留在样本并打标签，删掉它们会让多元公司从价值截面消失，造成另一种幸存者。地域收入不当成可空头的国家指数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写分部会计准则逐条，不做国家风险教科书。指数与行业配额仍用证券级分类，除非你明确改用分部加权暴露。后课默认：主干因子仍来自合并 PIT 字段；分部只作暴露修正，且附注可用日期更晚。</p><p>后课租赁与 NCI 仍在合并层修正，分部不能替代。年报附注的可用日期通常等于年报公告，日频因子不要在季报日抢用尚未披露的分部。管理层重切分部时，保留旧切割的历史权重直到新附注可用，这是 PIT，不是「保持可比」的重述。</p><p>后课默认主干因子仍来自合并 PIT 字段，分部只作暴露修正，且附注可用日期通常不早于年报公告。</p><p>分部重组当年，新旧切割并存时只使用当时附注给出的那一套，不要为了时间序列光滑而用新切割重做旧年收入。这与 restated 财报是同一类前视，只是发生在附注层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合并字段是因子主干；分部是拆分信息，不是第二套报表。</li><li>分部切割会改，必须按当时附注 PIT，不能新切割回填。</li><li>分部利润通常税前、未分摊共同费用，不能当独立 EPS。</li><li>可用日期往往等于年报公告，日频信号不要抢跑附注。</li><li>不披露分部的公司要留在宇宙并标记。</li><li>出处：SFAS 131 / IFRS 8；Penman 分部分析。</li></ul>',12))])}const f=o(E,[["render",c]]);export{T as __pageData,f as default};
